    }

    // Handle -h
    // ffmpeg -h, -h long, -h full, -h type=name
    // We need to parse -h args
    let mut h_index = None;
    for (i,a) in args.iter().enumerate() {
        if a == "-h" || a == "-?" || a == "-help" || a == "--help" {
            h_index = Some(i);
            break;
        }
    }
    if let Some(i) = h_index {
        // Look at next arg if exists and doesn't start with -
        let next = if i+1 < args.len() { Some(args[i+1].as_str()) } else { None };
        match next {
            None => {
                // basic
                let out = std::fs::read_to_string("/tmp/captured/h_out.txt").unwrap_or_default();
                let err = std::fs::read_to_string("/tmp/captured/h_err.txt").unwrap_or_else(|_| VERSION_BANNER.to_string());
