    // Now handle conversion: parse -i inputs and output
    // Simplified parsing: collect inputs with -i, and output is last arg that doesn't start with - and not value of option that requires value.

    // We need to handle -y, -n, -loglevel, -hide_banner, -f, -c:a, -c:v, etc.

    // For now, parse sequentially
    let mut inputs: Vec<String> = Vec::new();
    let mut outputs: Vec<String> = Vec::new();
    let mut i = 1;
    let mut last_format: Option<String> = None;
    let mut last_codec_a: Option<String> = None;
    let mut overwrite = false;
    let mut hide_banner = false;
    while i < args.len() {
        let a = &args[i];
        if a == "-i" {
            if i+1 < args.len() {
                inputs.push(args[i+1].clone());
