            if i+1 < args.len() && !args[i+1].starts_with("-") {
                // check if this option expects value? For -an, -vn, -sn, no value
                // For -ac, -ar, etc, expect value
                // We'll just skip next if not obviously an output file with extension?
                // For simplicity, skip
                i+=2;
