    let out_fmt = last_format.clone().unwrap_or(output_ext.clone());
    let out_fmt = out_fmt.to_lowercase();

    // Check for unknown format
    let known_mux = std::fs::read_to_string("/tmp/list_mux.txt").unwrap_or_default();
