fn encode_utf8(mut val: u64) -> Vec<u8> {
    // FLAC UTF-8: encode as per spec
    // For values <128, 1 byte
    // else, encode with leading bits indicating length, and continuation bytes 10xxxxxx
    // This is similar to UTF-8 but for up to 36 bits, max 7 bytes
    // Implement as per libFLAC
    if val < 0x80 {
        return vec![val as u8];
    }
    // Determine number of bytes needed
    // We'll implement generic: find minimal bytes
    // For simplicity, use algorithm from FLAC spec
    let mut bytes = Vec::new();
    // Count bits needed
    let mut n = 0;
    let mut tmp = val;
    while tmp>0 {
        n+=1;
        tmp>>=1;
    }
    // Number of bytes: ceil((n - 1) /5) ??? Let's just use standard UTF-8 lengths
    // For FLAC, encoding is:
    // 2 bytes: 110xxxxx 10xxxxxx (11 bits)
    // 3 bytes: 1110xxxx 10xxxxxx 10xxxxxx (16 bits)
    // etc.
    // We'll just implement for up to 36 bits
    if val < 0x800 { // 11 bits, 2 bytes
        bytes.push(0xC0 | ((val>>6) as u8 & 0x1F));
        bytes.push(0x80 | (val as u8 & 0x3F));
    } else if val < 0x10000 { // 16 bits, 3 bytes
        bytes.push(0xE0 | ((val>>12) as u8 & 0x0F));
        bytes.push(0x80 | ((val>>6) as u8 & 0x3F));
        bytes.push(0x80 | (val as u8 & 0x3F));
    } else if val < 0x200000 { // 21 bits, 4 bytes
        bytes.push(0xF0 | ((val>>18) as u8 & 0x07));
        bytes.push(0x80 | ((val>>12) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>6) as u8 & 0x3F));
        bytes.push(0x80 | (val as u8 & 0x3F));
    } else if val < 0x4000000 { // 26 bits, 5 bytes
        bytes.push(0xF8 | ((val>>24) as u8 & 0x03));
        bytes.push(0x80 | ((val>>18) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>12) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>6) as u8 & 0x3F));
        bytes.push(0x80 | (val as u8 & 0x3F));
    } else if val < 0x80000000 { // 31 bits, 6 bytes
        bytes.push(0xFC | ((val>>30) as u8 & 0x01));
        bytes.push(0x80 | ((val>>24) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>18) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>12) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>6) as u8 & 0x3F));
        bytes.push(0x80 | (val as u8 & 0x3F));
    } else { // up to 36 bits, 7 bytes
        bytes.push(0xFE);
        bytes.push(0x80 | ((val>>30) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>24) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>18) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>12) as u8 & 0x3F));
        bytes.push(0x80 | ((val>>6) as u8 & 0x3F));
        bytes.push(0x80 | (val as u8 & 0x3F));
    }
    bytes
}

fn md5_compute(data: &[u8]) -> [u8;16] {
