            eprintln!("Error opening output files: Invalid argument");
            std::process::exit(234);
        }
    }

    if let Some(codec) = &last_codec_a {
        let known_enc = include_str!("/tmp/list_enc3.txt");
        if !known_enc.lines().any(|l| l==codec) {
            eprint!("{}", VERSION_BANNER);
            if input_ext=="wav" {
                eprintln!("[aist#0:0/pcm_s16le @ 0x...] Guessed Channel Layout: mono");
                eprintln!("Input #0, wav, from '{}':", input_path);
                eprintln!("  Metadata:");
